   {
       if (isset($_SESSION['sc_session'][$this->Ini->sc_page]['cons_item_custos']['ini_cor_grid']) && $_SESSION['sc_session'][$this->Ini->sc_page]['cons_item_custos']['ini_cor_grid'] == "impar")
       {
           $this->Ini->qual_linha = "impar";
           unset($_SESSION['sc_session'][$this->Ini->sc_page]['cons_item_custos']['ini_cor_grid']);
       }
   }
   static $nm_seq_execucoes = 0; 
