   $SC_Label = (isset($this->New_label['calc_desc_item'])) ? $this->New_label['calc_desc_item'] : "Desc.Item";
   $_SESSION['sc_session'][$this->Ini->sc_page]['cons_item_custos']['labels']['calc_desc_item'] = $SC_Label; 
   $SC_Label = (isset($this->New_label['dt_hr_custo'])) ? $this->New_label['dt_hr_custo'] : "Data/Hora ";
   $_SESSION['sc_session'][$this->Ini->sc_page]['cons_item_custos']['labels']['dt_hr_custo'] = $SC_Label; 
   $SC_Label = (isset($this->New_label['cod_tipo_custo'])) ? $this->New_label['cod_tipo_custo'] : "Tipo Custo";
   $_SESSION['sc_session'][$this->Ini->sc_page]['cons_item_custos']['labels']['cod_tipo_custo'] = $SC_Label; 
