   $_SESSION['sc_session'][$this->Ini->sc_page]['cons_item_custos']['labels']['cod_situacao'] = $SC_Label; 
   $SC_Label = (isset($this->New_label['calc_container'])) ? $this->New_label['calc_container'] : "Container";
   $_SESSION['sc_session'][$this->Ini->sc_page]['cons_item_custos']['labels']['calc_container'] = $SC_Label; 
