   $_SESSION['sc_session'][$this->Ini->sc_page]['cons_item_custos']['labels']['caminho_arquivo'] = $SC_Label; 
   if (!$this->grid_emb_form && isset($_SESSION['scriptcase']['sc_apl_conf']['cons_item_custos']['lig_edit']) && $_SESSION['scriptcase']['sc_apl_conf']['cons_item_custos']['lig_edit'] != '')
