 function NM_grid_dt_hr_custo()
 {
      global $nm_saida;
      if (!isset($this->NM_cmp_hidden['dt_hr_custo']) || $this->NM_cmp_hidden['dt_hr_custo'] != "off") { 
          $conteudo = NM_encode_input(sc_strip_script($this->dt_hr_custo)); 
          $conteudo_original = NM_encode_input(sc_strip_script($this->dt_hr_custo)); 
          if ($conteudo === "") 
          { 
              $conteudo = "&nbsp;" ;  
              $graf = "" ;  
          } 
          else    
          { 
               if (substr($conteudo, 10, 1) == "-") 
               { 
                  $conteudo = substr($conteudo, 0, 10) . " " . substr($conteudo, 11);
               } 
               if (substr($conteudo, 13, 1) == ".") 
               { 
                  $conteudo = substr($conteudo, 0, 13) . ":" . substr($conteudo, 14, 2) . ":" . substr($conteudo, 17);
